"""`.NSFW positioning`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.NSFW positioning'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Right nipple', 'NodeSocketVector', min_value=0.0, max_value=0.0)
    t.socket('OUTPUT', 'Left nipple', 'NodeSocketVector', min_value=0.0, max_value=0.0)
    t.socket('OUTPUT', 'Underhair', 'NodeSocketVector', min_value=0.0, max_value=0.0)

    t.node('NodeFrame', 'Frame.002', props={
        'location': (-455.0526, 300.5263),
        'width': 584.3567,
        'height': 280.0,
        'label': 'Position and scale nipples',
    })
    t.node('NodeFrame', 'Frame', props={
        'location': (-453.1579, 0.5263214),
        'width': 585.3627,
        'height': 276.8421,
        'label': 'Position underhair',
    })
    t.node('NodeGroupOutput', 'Group Output', props={
        'location': (169.27475, 85.134056),
    })
    t.node('ShaderNodeGroup', 'Group.001', parent='Frame', props={
        'node_tree': lib.group('Scale Vector'),
        'location': (354.0973, -39.723312),
        'width': 201.99423,
    })
    t.node('ShaderNodeGroup', 'Group', parent='Frame.002', props={
        'node_tree': lib.group('Scale Vector'),
        'location': (344.39606, -39.756653),
        'width': 210.46194,
    })
    t.node('ShaderNodeUVMap', 'underuv', parent='Frame', props={
        'location': (29.650879, -109.191696),
        'width': 150.0,
        'uv_map': 'uv_underhair',
    })
    t.node('ShaderNodeUVMap', 'nippleuv', parent='Frame.002', props={
        'location': (29.28424, -138.7146),
        'width': 150.0,
        'uv_map': 'uv_nipple_and_shine',
    })

    t.link('nippleuv', 'UV', 'Group', 'UV Map')
    t.link('Group', 'Coordinates', 'Group Output', 'Right nipple')
    t.link('Group.001', 'Coordinates', 'Group Output', 'Underhair')
    t.link('Group', 'Coordinates', 'Group Output', 'Left nipple')
    t.link('underuv', 'UV', 'Group.001', 'UV Map')
    return t
